code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    boxes = []
    for color in sorted({v for row in grid for v in row if v != 0}):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
        c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        edge = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                if r in (r0,r1) or c in (c0,c1)}
        if set(cells) == edge:
            boxes.append((color,r0,r1,c0,c1))
    frame_cells = {(r,c) for color,r0,r1,c0,c1 in boxes
                   for r in range(r0,r1+1) for c in range(c0,c1+1)
                   if r in (r0,r1) or c in (c0,c1)}
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != 0 and (r,c) not in frame_cells)
    fillers = list(counts.items())
    # Assign each non-frame color to the frame with closest checkerboard capacity.
    boxes.sort(key=lambda b:(b[1],b[3]))
    fillers.sort(key=lambda x:-x[1])
    capacities = [sum(1 for r in range(b[1]+1,b[2]) for c in range(b[3]+1,b[4])
                      if (r-b[1]-1+c-b[3]-1)%2==0) for b in boxes]
    # Small task has matching source-dot counts; greedy minimum distance works for this stream.
    assigned = {}
    remaining = set(range(len(fillers)))
    for bi, cap in sorted(enumerate(capacities), key=lambda x:x[1]):
        if remaining:
            fi=min(remaining,key=lambda i:(abs(fillers[i][1]-cap), -fillers[i][1]))
            assigned[bi]=fillers[fi][0]; remaining.remove(fi)
    out=[[0]*w for _ in range(h)]
    for bi,(color,r0,r1,c0,c1) in enumerate(boxes):
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1): out[r][c]=color
                elif (r-r0-1+c-c0-1)%2==0 and bi in assigned: out[r][c]=assigned[bi]
    return out
'''
